SELECT n.nspname AS schema, c.relname AS tabla, t.tgname AS trigger, t.tgenabled, p.proname AS funcion FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_proc p ON p.oid=t.tgfoid WHERE n.nspname='public' AND NOT t.tgisinternal AND (c.relname LIKE 'fin\_%' ESCAPE '\' OR c.relname IN ('payrolls','payroll_items','payroll_item_concepts','worker_salary_rates')) ORDER BY c.relname, t.tgname;
